// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount, uint96 smallSeed) public {
        vm.assume(amount > 0);
        vm.assume(amount <= type(uint256).max - 1);

        address user = address(uint160(uint256(keccak256(abi.encode(smallSeed)))));
        vm.assume(user != address(0));

        vm.deal(user, amount);

        uint256 initialBalance = c.getBalance(user);

        vm.prank(user);
        try c.addToBalance{value: amount}() { }
        catch { }

        uint256 finalBalance = c.getBalance(user);
        assertTrue(finalBalance == initialBalance + amount);
    }
}
